7: 
8: /** In reading order: who the customers are, where competitors reach, and what that leaves. */
9: export const LAYERS: { id: LayerId; label: string; low: string; high: string }[] = [
10:   { id: "fit", label: "Customers", low: "Few", high: "Many" },
11:   { id: "competition", label: "Competitors", low: "No confirmed ads nearby", high: "Confirmed current ads" },
12:   { id: "gap", label: "Gap", low: "Covered or few customers", high: "High fit, no confirmed ads" },
13: ];
14: 
15: /** Picks the layer the map shows and the results column explains. */
16: export function LayerTabs({ layer, onChange }: { layer: LayerId; onChange: (layer: LayerId) => void }) {
17:   const items = useRef(new Map<LayerId, HTMLElement>());
18:   const [pill, setPill] = useState<{ left: number; width: number } | null>(null);
19: 
20:   // The pill is one element that moves under the pressed tab, so the change
21:   // slides instead of jumping. It is measured again when the tabs resize.
22:   useLayoutEffect(() => {
23:     const el = items.current.get(layer);
24:     if (!el) return;
25:     const measure = () => setPill({ left: el.offsetLeft, width: el.offsetWidth });
26:     measure();
27:     const observer = new ResizeObserver(measure);
28:     observer.observe(el);
29:     return () => observer.disconnect();
30:   }, [layer]);
31: 
32:   return (
33:     <ToggleGroup
34:       aria-label="Map layer"
35:       value={[layer]}
36:       onValueChange={(v) => {
37:         const next = LAYERS.find((l) => l.id === v[0]);
38:         if (next) onChange(next.id);
39:       }}
40:       spacing={0}
41:       className="relative w-full rounded-full bg-foreground/5 p-1"
42:     >
43:       {pill && (
44:         <span
45:           aria-hidden
46:           className="absolute inset-y-1 rounded-full bg-foreground transition-[left,width] duration-300 ease-out motion-reduce:transition-none"
47:           style={{ left: pill.left, width: pill.width }}
48:         />
49:       )}
50:       {LAYERS.map((l) => (
51:         <ToggleGroupItem
52:           key={l.id}
53:           value={l.id}
54:           ref={(el: HTMLButtonElement | null) => {
55:             if (el) items.current.set(l.id, el);
56:             else items.current.delete(l.id);
57:           }}
58:           // The sliding pill is the only background; a tab painting its own
59:           // (the toggle's hover and pressed greys) would flash over the pill.
60:           className="relative h-8 flex-1 rounded-full! bg-transparent px-2 text-sm text-foreground/60 transition-[color] duration-300 hover:bg-transparent hover:text-foreground aria-pressed:bg-transparent aria-pressed:text-background aria-pressed:hover:text-background motion-reduce:transition-none"
61:         >
62:           {l.label}
63:         </ToggleGroupItem>
64:       ))}
65:     </ToggleGroup>
66:   );
67: }

