15: // MapLibre looks for its worker next to its own module, where the bundler
16: // leaves nothing. This hands the bundler the worker file to emit and serve.
17: setWorkerUrl(new URL("maplibre-gl/dist/maplibre-gl-worker.mjs", import.meta.url).href);
