21: // alpha rising from 0.15 to 0.75 so weak tracts let the basemap show through.
22: function heatRamp(id: LayerId): ExpressionSpecification {
23:   return [
24:     "interpolate", ["linear"], ["get", id],
25:     0, "rgba(43, 89, 195, 0.15)",
26:     0.5, "rgba(242, 177, 52, 0.45)",
27:     1, "rgba(224, 51, 79, 0.75)",
28:   ];
29: }
