12: /** The heatmap's colour for a score from 0 to 1. */
13: export function heatColor(score: number) {
14:   return score < 0.5
15:     ? `color-mix(in oklch, var(--heat-mid) ${score * 200}%, var(--heat-cool))`
16:     : `color-mix(in oklch, var(--heat-hot) ${(score - 0.5) * 200}%, var(--heat-mid))`;
