21: /** How many tracts each tab ranks. */
22: const TOP_TRACTS = 5;
23: 
24: /** The selected layer, the campaigns found so far, the map layers they produce and the focused placement. */
25: export function useRunView(run: RunState) {
26:   const [layer, setLayer] = useState<LayerId>("gap");
27:   const campaigns = useMemo(() => campaignsOf(run.events), [run.events]);
28:   const layers = useMemo(
29:     () => (run.shapes && run.fit ? computeLayers(run.shapes, run.fit, campaigns) : null),
30:     [run.shapes, run.fit, campaigns],
31:   );
