36: function Section({ title, aside, children }: { title: string; aside?: React.ReactNode; children: React.ReactNode }) {
37:   return (
38:     <section className="flex flex-col gap-3">
39:       <div className="flex items-baseline justify-between gap-3">
40:         <h2 className="font-heading text-lg font-semibold tracking-tight">{title}</h2>
41:         {aside && <span className="font-mono text-xs text-muted-foreground">{aside}</span>}
42:       </div>
43:       {children}
44:     </section>
45:   );
46: }
