325:         emit({ type: "error", message: stageSignal.aborted ? `${competitor.name}: campaign search reached its time limit. Findings are partial.` : `${competitor.name}: ${agentFailure(error)}` });
326:         throw error;
327:       }
328:     }));
329:     signal.throwIfAborted();
330:     const complete = discoveryState.finished && outcomes.every((outcome) => outcome.status === "fulfilled" && outcome.value);
331:     const timedOut = discoveryTimedOut || outcomes.some((outcome) => outcome.status === "rejected" && outcome.reason instanceof Error && ["TimeoutError", "AbortError"].includes(outcome.reason.name));
332:     summary.status = complete ? "complete" : timedOut ? "timed-out" : summary.competitorsSearched.length || competitors.size ? "partial" : "failed";
333:     emit({ type: "step", message: `Research ${summary.status}: ${competitors.size} competitors and ${campaigns.size} campaign findings. Missing evidence remains unknown coverage.` });
334:     return complete;
335:   } catch (error) {
336:     summary.status = signal.aborted ? "timed-out" : "failed";
337:     throw error;
338:   } finally {
339:     summary.sources = sources.size;
340:     emit({ type: "research", summary });
341:   }
342: }
343: 
344: export async function replayCompetitorResearch(brief: Brief, emit: (event: AgentEvent) => void) {
345:   let recording: { recordedAt: string; brief: Brief; events: AgentEvent[] };
346:   try {
347:     recording = JSON.parse(await readFile(path.join(process.cwd(), "..", "data", "competitors", "sample-run.json"), "utf8"));
348:   } catch (error) {
349:     if (error instanceof Error && "code" in error && error.code === "ENOENT") return false;
350:     throw error;
351:   }
352:   const identity = (input: Brief) => JSON.stringify([input.city, input.industry, input.description, input.targetCustomer]);
353:   if (identity(recording.brief) !== identity(brief)) return false;
354:   emit({ type: "recording", recordedAt: recording.recordedAt });
355:   const today = new Date().toISOString().slice(0, 10);
356:   for (const event of recording.events) {
357:     if (event.type === "competitor") emit(event);
358:     if (event.type === "campaign") emit({ type: "campaign", campaign: {
359:       ...event.campaign,
360:       coverage: campaignCoverage(event.campaign.startsOn, event.campaign.endsOn, today),
361:     } });
362:   }
363:   return true;
364: }

